   ((1)::numeric = ANY (ARRAY[(2)::numeric, (3)::numeric])) AS numeric_value,
   ((ARRAY[1] = ARRAY[1]) OR (ARRAY[1] = ARRAY[2])) AS arrays;

SELECT (((( SELECT ia_probe('ia_target'::regclass) AS ia_probe))::oid = (c)::oid) OR ((( SELECT ia_probe('ia_target'::regclass) AS ia_probe))::oid = ('ia_target'::regclass)::oid)) AS subleft,
   (((ia_probe('ia_target'::regclass))::oid = ANY ((ARRAY['ia_target'::regclass, 'ia_other'::regclass])::oid[])) OR ((ia_probe('ia_target'::regclass))::oid = (( SELECT ia_source.c))::oid)) AS subright
